/* ==========================================
   1. CONTENEDOR PRINCIPAL: RZK_Device
   ========================================== */
.RZK_Device {
  --glowcolor: #dd77be;
  width: 620px;
  height: 500px;
  border-radius: 2cap;
  position: relative;
  box-sizing: border-box;

  display: flex;
  justify-content: center;
  align-items: center;

  background-color: #121314;
  background-image: radial-gradient(
      circle at 50% 0%,
      rgba(255, 255, 255, 0.08),
      transparent 60%
    ),
    repeating-linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.012) 0px,
      rgba(255, 255, 255, 0.012) 1px,
      transparent 1px,
      transparent 2px
    ),
    linear-gradient(135deg, #24272a 0%, #151718 35%, #0d0e0f 70%, #1e2022 100%);

  border: 1px solid #2b2e31;
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.2),
    inset 0 -2px 8px rgba(0, 0, 0, 0.8),
    0 0 0 1px #050506,
    0 20px 40px -10px rgba(0, 0, 0, 0.85);

  overflow: hidden;
}

/* ==========================================
   2. ADITAMENTO DE CRISTAL: RZK_Device__glass
   ========================================== */
.RZK_Device__glass {
  width: 600px;
  height: 480px;
  border-radius: 2cap;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;

  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  padding: 15px;

  background: rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(13px);
  -webkit-backdrop-filter: blur(13px);

  border: 1px solid rgba(255, 255, 255, 0.25);
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.5),
    inset 0 -1px 0 rgba(255, 255, 255, 0.15),
    inset 0 0 30px rgba(255, 255, 255, 0.08);
}

.RZK_Device__glass::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.8),
    transparent
  );
  z-index: 2;
}

.RZK_Device__glass::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 2px;
  height: 100%;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.8),
    transparent,
    rgba(255, 255, 255, 0.3)
  );
  z-index: 2;
}

/* ==========================================
   3. PANEL TECLADO: RZK_Device__keypad
   ========================================== */
.RZK_Device__keypad {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  height: 100%;
  width: 280px;
  flex-shrink: 0;
  padding: 0px;
  border-radius: 16px;
  box-sizing: border-box;
  z-index: 3;
}

/* ==========================================
   4. TECLAS / BOTONES: RZK_Device__key
   ========================================== */
.RZK_Device__key {
  all: unset;
  position: relative;
  height: 4em;
  width: 4em;
  padding: 5px;
  border-radius: 10px;
  box-sizing: border-box;

  --btn-color: #232323bd;
  --btn-text: #ffffff;

  --base-start: color-mix(in srgb, var(--btn-color) 80%, #000);
  --base-end: color-mix(in srgb, var(--btn-color) 60%, #000);

  background: linear-gradient(180deg, var(--base-start), var(--base-end));
  box-shadow:
    inset -6px 0 6px rgba(0, 0, 0, 0.2),
    inset 0 -6px 6px rgba(0, 0, 0, 0.3),
    0 0 0 2px rgba(0, 0, 0, 0.75),
    4px 8px 15px rgba(0, 0, 0, 0.4);

  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  transition:
    transform 0.08s ease,
    box-shadow 0.08s ease;
}

.RZK_Device__key::before {
  content: "";
  position: absolute;
  top: 3px;
  left: 5px;
  bottom: 12px;
  right: 7px;

  --face-start: var(--btn-color);
  --face-end: color-mix(in srgb, var(--btn-color) 82%, #fff);

  background: linear-gradient(90deg, var(--face-start), var(--face-end));
  border-radius: 8px;
  box-shadow: 6px 4px 8px rgba(0, 0, 0, 0.2);
  border-left: 2px solid rgba(0, 0, 0, 0.25);
  border-bottom: 1px solid rgba(0, 0, 0, 0.25);
  border-top: 2px solid rgba(255, 255, 255, 0.4);
}

.RZK_Device__key:active {
  background: radial-gradient(
    color-mix(in srgb, var(--btn-color) 5%, var(--glowcolor)),
    var(--btn-color)
  );
  transform: translateY(2px);

  box-shadow:
    inset -4px 0 4px rgba(0, 0, 0, 0.1),
    inset 0 -4px 4px rgba(0, 0, 0, 0.15),
    0 0 0 2px rgba(0, 0, 0, 0.5),
    5px 10px 15px rgba(0, 0, 0, 0.3),
    0 0 15px 0 var(--glowcolor),
    0 0px 85px 0 var(--glowcolor);

  &::before {
    background: radial-gradient(
      color-mix(in srgb, var(--btn-color) 1%, var(--glowcolor)),
      var(--btn-color)
    );
    box-shadow:
      -5px -5px 5px rgba(255, 255, 255, 0.15),
      5px 3px 5px rgba(0, 0, 0, 0.1);
  }
}

.RZK_Device__key span {
  font-family:
    system-ui,
    -apple-system,
    sans-serif;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--btn-text);
  position: relative;
  margin-top: -6px;
  user-select: none;
}

.RZK_Device__key svg {
  width: 2.1em;
  height: 2.1em;
  color: var(--btn-text);
  fill: currentColor;
  stroke: currentColor;
  position: relative;
  margin-top: -6px;
}

/* ==========================================
   5. PANEL DERECHO (PANTALLA + JOYSTICK)
   ========================================== */
.RZK_Device__right-panel {
  flex: 1;
  height: 100%;
  width: 50%;
  display: flex;
  flex-direction: column;
  gap: 0px;
  z-index: 3;
}

/* Pantalla (Mitad de Alto) */
.RZK_Device__screen {
  flex: 2;
  width: 100%;
  border-radius: 14px;
  box-sizing: border-box;
  position: relative;
  --padding: 5px;
  --transition: 0.4s;
  --button-color: #101010;
  --highlight-color-hue: 210deg;
  background-color: var(--button-color);

  box-shadow:
    inset 0px 1px 1px rgba(255, 255, 255, 0.2),
    inset 0px 2px 2px rgba(255, 255, 255, 0.15),
    inset 0px 4px 4px rgba(255, 255, 255, 0.1),
    inset 0px 8px 8px rgba(255, 255, 255, 0.05),
    inset 0px 16px 16px rgba(255, 255, 255, 0.05),
    0px -1px 1px rgba(0, 0, 0, 0.5),
    0px -2px 2px rgba(0, 0, 0, 0.03),
    0px -4px 4px rgba(0, 0, 0, 0.05),
    0px -8px 8px rgba(0, 0, 0, 0.2),
    0px -16px 16px rgba(0, 0, 0, 0.1);

  border: solid 1px #fff2;
  cursor: pointer;
}

/* ==========================================
   6. COMPONENTE JOYSTICK REFACTORIZADO
   ========================================== */
.RZK_Joystick {
  flex: 1;
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  border-radius: 14px;
  cursor: pointer;
  overflow: hidden;
}

.RZK_Joystick__wrapper {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  transform: scale(
    0.5
  ); /* Se redujo de 0.53 a 0.42 para encajar perfectamente dos joysticks */
}

/* Zonas de Touch para Hover 3D */
.RZK_Joystick__touch {
  position: absolute;
  display: flex;
  flex-wrap: wrap;
  z-index: 999;
  width: 600px;
  height: 600px;
  transform: rotate(45deg);
}

.RZK_Joystick__t {
  width: 300px;
  height: 300px;
}

.RZK_Device__joysticks-container {
  flex: 1;
  width: 100%;
  height: 20%;
  display: flex;
  flex-direction: row; /* Coloca los joysticks lado a lado */
  gap: 2px;
  align-items: center;
  justify-content: space-between;
}

/* Base del Palillo */
.RZK_Joystick__around {
  width: 180px;
  height: 180px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-width: 2cap;
  border-radius: 50%;
  border-top: #3c3ce9;

  background-image: linear-gradient(-45deg, #8f8f8f, #161616);
}

.RZK_Joystick__handle {
  width: 155px;
  height: 155px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 50%;
  background: #2e2e2e;
  box-shadow:
    0 0 10px rgba(0, 0, 0, 0.5),
    0 10px 10px rgba(0, 0, 0, 0.2),
    inset 0 0 16px rgba(0, 0, 0, 0.85),
    inset 0 0 24px rgba(0, 0, 0, 0.75),
    inset 0 0 48px rgba(0, 0, 0, 0.2);
  perspective: 300px;
}

.RZK_Joystick__button-wrapper {
  width: 102px;
  height: 102px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 50%;
  background-image: linear-gradient(0deg, #1b1b1b, #4e4e4e);
  box-shadow:
    0 9px 14px rgba(0, 0, 0, 0.5),
    0 19px 8px -2px rgba(0, 0, 0, 0.2),
    0 33px 8px rgba(0, 0, 0, 0.4),
    0 -12px 10px rgba(29, 29, 29, 0.5),
    inset 0 3px 3px rgba(80, 79, 79, 0.6),
    inset 0 -3px 3px rgba(62, 63, 63, 0.6);
  transition:
    transform 0.25s ease-out,
    box-shadow 0.25s ease-out;
}

.RZK_Joystick__inside {
  position: relative;
  width: 85px;
  height: 85px;
  border-radius: 50%;
  background-image: linear-gradient(180deg, #202020, #5c5b5b);
  box-shadow:
    inset 0 3px 6px rgba(152, 160, 163, 0.4),
    inset 0 -3px 6px rgba(238, 244, 246, 0.4);
}

.RZK_Joystick__dot {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #bcbfc0;
  box-shadow:
    0 2px 2px rgba(0, 0, 0, 0.3),
    inset 0 -2px 2px rgba(0, 0, 0, 0.2);
}

.RZK_Joystick__dot:nth-child(1) {
  left: 50%;
  top: 10%;
}
.RZK_Joystick__dot:nth-child(2) {
  left: 90%;
  top: 50%;
}
.RZK_Joystick__dot:nth-child(3) {
  left: 50%;
  top: 90%;
}
.RZK_Joystick__dot:nth-child(4) {
  left: 10%;
  top: 50%;
}

/* Iconos de Dirección */
.RZK_Joystick__icon {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 30px;
  fill: #b4b9bd;
  filter: drop-shadow(1px 1px 1px #f4f4f4);
  transition:
    fill 0.2s,
    filter 0.2s;
}

.RZK_Joystick__icon--top {
  top: -12%;
  left: 50%;
}
.RZK_Joystick__icon--right {
  top: 50%;
  left: 112%;
}
.RZK_Joystick__icon--bottom {
  top: 112%;
  left: 50%;
}
.RZK_Joystick__icon--left {
  top: 50%;
  left: -12%;
}

/* Interacciones Hover en las Direcciones */
.RZK_Joystick__wrapper:has(.RZK_Joystick__t1:hover)
  .RZK_Joystick__button-wrapper {
  transform-style: preserve-3d;
  transform: translate(0, -15px) rotateX(8deg);
  box-shadow:
    0 7px 14px rgba(0, 0, 0, 0.5),
    0 14px 8px -5px rgba(0, 0, 0, 0.3),
    0 24px 8px rgba(0, 0, 0, 0.4),
    0 -6px 10px rgba(255, 255, 255, 0.5),
    inset 0 3px 3px rgba(255, 255, 255, 0.6),
    inset 0 -3px 3px rgba(89, 91, 92, 0.6) !important;
}

.RZK_Joystick__wrapper:has(.RZK_Joystick__t1:hover) .RZK_Joystick__icon--top {
  fill: #eaa75d;
  filter: brightness(0.9) drop-shadow(0 0 2px #f1b475) drop-shadow(0 0 1px #fff);
}

.RZK_Joystick__wrapper:has(.RZK_Joystick__t2:hover)
  .RZK_Joystick__button-wrapper {
  transform-style: preserve-3d;
  transform: translate(15px, 0) rotateY(8deg);
  box-shadow:
    2px 9px 14px rgba(0, 0, 0, 0.4),
    2px 19px 8px -2px rgba(0, 0, 0, 0.2),
    2px 30px 8px rgba(0, 0, 0, 0.3),
    -6px -14px 10px rgba(255, 255, 255, 0.5),
    inset 0 3px 3px rgba(255, 255, 255, 0.6),
    inset 0 -3px 3px rgba(89, 91, 92, 0.6) !important;
}

.RZK_Joystick__wrapper:has(.RZK_Joystick__t2:hover) .RZK_Joystick__icon--right {
  fill: #e3a560;
  filter: brightness(0.9) drop-shadow(0 0 2px #e3a15b) drop-shadow(0 0 1px #fff);
}

.RZK_Joystick__wrapper:has(.RZK_Joystick__t3:hover)
  .RZK_Joystick__button-wrapper {
  transform-style: preserve-3d;
  transform: translate(-15px, 0) rotateY(-8deg);
  box-shadow:
    -2px 9px 14px rgba(0, 0, 0, 0.4),
    -2px 19px 8px -2px rgba(0, 0, 0, 0.2),
    -2px 30px 8px rgba(0, 0, 0, 0.3),
    6px -14px 10px rgba(255, 255, 255, 0.5),
    inset 0 3px 3px rgba(255, 255, 255, 0.6),
    inset 0 -3px 3px rgba(89, 91, 92, 0.6) !important;
}

.RZK_Joystick__wrapper:has(.RZK_Joystick__t3:hover) .RZK_Joystick__icon--left {
  fill: #e3a560;
  filter: brightness(0.9) drop-shadow(0 0 2px #e3a15b) drop-shadow(0 0 1px #fff);
}

.RZK_Joystick__wrapper:has(.RZK_Joystick__t4:hover)
  .RZK_Joystick__button-wrapper {
  transform-style: preserve-3d;
  transform: translate(0, 15px) rotateX(-8deg);
  box-shadow:
    0 5px 14px rgba(0, 0, 0, 0.6),
    0 19px 8px -2px rgba(0, 0, 0, 0.3),
    0 34px 8px rgba(0, 0, 0, 0.4),
    0 -14px 10px rgba(255, 255, 255, 0.65),
    inset 0 3px 3px rgba(255, 255, 255, 0.6),
    inset 0 -3px 3px rgba(89, 91, 92, 0.6) !important;
}

.RZK_Joystick__wrapper:has(.RZK_Joystick__t4:hover)
  .RZK_Joystick__icon--bottom {
  fill: #e3a560;
  filter: brightness(0.9) drop-shadow(0 0 2px #e3a15b) drop-shadow(0 0 1px #fff);
}
